/**
 * Dashboard Viewer MCP App
 *
 * Renders dashboard specs generated by Claude Desktop.
 * The spec is passed via query parameter or tool context.
 */

import * as React from 'react';
import { createRoot } from 'react-dom/client';
import {
  Renderer,
  StateProvider,
  ActionProvider,
  VisibilityProvider,
  type Spec,
} from '@json-render/react';
import { McpAppsBridge } from '../bridge/McpAppsBridge';
import { McpBridgeProvider } from '../bridge/McpBridgeProvider';
import { ThemeProvider } from '../theme/ThemeProvider';
import { ChartThemeProvider } from '../theme/ChartThemeProvider';
import { ThemeToggle } from './ThemeToggle';
import { ChartThemeSelector } from './ChartThemeSelector';
import { Logo } from './Logo';
import { dashboardRegistry } from './dashboard-registry';
import { MCPDebugPanel } from './MCPDebugPanel';
import { EmptyState } from '../molecules/empty-state/EmptyState';
import { AlertCircle } from 'lucide-react';
import '../theme/tokens.css';

// Enable debug panel for development (set to false for production)
const ENABLE_DEBUG = true;

// Create the MCP Apps bridge instance for tool calls
const bridge = new McpAppsBridge();
bridge.connect();


function DashboardViewer() {
  const [spec, setSpec] = React.useState<Spec | null>(null);
  const [initialState, setInitialState] = React.useState<Record<string, unknown>>({});
  const [status, setStatus] = React.useState<'loading' | 'no-data' | 'ready'>('loading');

  React.useEffect(() => {
    console.log('[DashboardViewer] Mounting and setting up message listener');

    const handleMessage = (event: MessageEvent) => {
      // Try to extract spec from various possible formats
      let receivedSpec: Spec | null = null;

      // Format 1: ui/notifications/tool-input message (from Claude Desktop)
      if (event.data?.method === 'ui/notifications/tool-input' && event.data?.params?.arguments?.spec) {
        console.log('[DashboardViewer] Received spec via tool-input notification');
        receivedSpec = event.data.params.arguments.spec;
      }
      // Format 2: Direct dashboardSpec
      else if (event.data?.dashboardSpec) {
        console.log('[DashboardViewer] Received spec via dashboardSpec');
        receivedSpec = event.data.dashboardSpec;
      }
      // Format 3: _meta.ui.dashboardSpec
      else if (event.data?._meta?.ui?.dashboardSpec) {
        console.log('[DashboardViewer] Received spec via _meta.ui.dashboardSpec');
        receivedSpec = event.data._meta.ui.dashboardSpec;
      }
      // Format 4: Message itself is a spec
      else if (event.data?.root && event.data?.elements) {
        console.log('[DashboardViewer] Received spec directly');
        receivedSpec = event.data;
      }

      if (receivedSpec) {
        console.log('[DashboardViewer] Setting up dashboard with root:', receivedSpec.root);
        console.log('[DashboardViewer] Using spec data:', receivedSpec.state?.data?.length || 0, 'items');

        setInitialState(receivedSpec.state || {});
        setSpec(receivedSpec);
        setStatus('ready');
      }
    };

    window.addEventListener('message', handleMessage);
    console.log('[DashboardViewer] Message listener attached');

    if (window.parent !== window) {
      console.log('[DashboardViewer] Notifying parent: ready');
      window.parent.postMessage({ type: 'dashboard-viewer-ready' }, '*');
    }

    // Longer timeout - only show "no data" if we're really sure nothing is coming
    // In MCP Apps, tool-input messages arrive within milliseconds, so 10 seconds is generous
    const timeout = setTimeout(() => {
      if (status === 'loading') {
        console.log('[DashboardViewer] No spec received after 10 seconds');
        setStatus('no-data');
      }
    }, 10000);

    return () => {
      window.removeEventListener('message', handleMessage);
      clearTimeout(timeout);
    };
  }, [status]);

  // Loading state - waiting for data
  if (status === 'loading') {
    return (
      <div className="min-h-screen bg-background text-foreground flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-4 border-outline border-t-primary mx-auto mb-4"></div>
          <p className="text-on-surface-variant">Loading dashboard...</p>
        </div>
      </div>
    );
  }

  // No dashboard data received after timeout
  if (status === 'no-data') {
    return (
      <div className="min-h-screen bg-background text-foreground">
        {ENABLE_DEBUG && <MCPDebugPanel />}
        <header className="sticky top-0 z-50 border-b border-border bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60">
          <div className="container mx-auto px-4 py-3 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Logo height={32} />
              <div className="text-sm text-muted-foreground">Dashboard Viewer</div>
            </div>
            <div className="flex items-center gap-2">
              <ChartThemeSelector />
              <ThemeToggle />
            </div>
          </div>
        </header>
        <main className="flex items-center justify-center min-h-[calc(100vh-64px)]">
          <EmptyState
            icon={<AlertCircle className="w-8 h-8" />}
            title="No Dashboard Data"
            description="No dashboard specification was received. Ask Claude to create a dashboard with your data to visualize it here."
          />
        </main>
      </div>
    );
  }

  // Ready - dashboard data received
  if (!spec) {
    // This shouldn't happen, but guard against it
    return null;
  }

  console.log('[DashboardViewer] Rendering with spec:', spec);

  return (
    <div className="min-h-screen bg-background text-foreground">
      {ENABLE_DEBUG && <MCPDebugPanel />}
      <header className="sticky top-0 z-50 border-b border-border bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60">
        <div className="container mx-auto px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Logo height={32} />
            <div className="text-sm text-muted-foreground">Dashboard Viewer</div>
          </div>
          <div className="flex items-center gap-2">
            <ChartThemeSelector />
            <ThemeToggle />
          </div>
        </div>
      </header>
      <main className="p-6">
        {spec ? (
          <>
            <StateProvider initialState={initialState}>
              <ActionProvider handlers={{}}>
                <VisibilityProvider>
                  <Renderer
                    spec={spec}
                    registry={dashboardRegistry}
                    loading={false}
                  />
                </VisibilityProvider>
              </ActionProvider>
            </StateProvider>
          </>
        ) : (
          <div className="text-center p-8">
            <p className="text-muted-foreground">No spec loaded</p>
          </div>
        )}
      </main>
    </div>
  );
}

// Render the application
const root = document.getElementById('root');
if (root) {
  createRoot(root).render(
    <McpBridgeProvider bridge={bridge}>
      <ThemeProvider persistTheme density="comfortable">
        <ChartThemeProvider persistTheme>
          <DashboardViewer />
        </ChartThemeProvider>
      </ThemeProvider>
    </McpBridgeProvider>
  );
}
